/// Returns true iff `v` starts with prefix `p`.
/// Matches the definition: empty prefix always matches; otherwise all positions
/// up to `p.len()` must be equal and `v.len() >= p.len()`.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

/// Filters `xs` to only those sequences starting with `p`, preserving order.
/// The output may be empty.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s);
        }
    }
    filtered
}

